-- 00029: replace estimated nutrition_foods with the full DOST-FNRI PhilFCT dataset.
--
-- Source: https://github.com/nedpals/fct-fnri-api (CC0) - 1542 foods scraped from
-- i.fnri.dost.gov.ph/fct. All values are per 100 g edible portion, which is what the
-- member food-intake wizard's grams-based quantity step expects.
--
--   food_name     <- name
--   aliases       <- alternative_name (Filipino), when present
--   category      <- food_group
--   serving       <- 100 g
--   calories_kcal <- energy_calculated_kcal
--   protein/carbs/fat <- protein_g / carbohydrate_total_g / total_fat_g
--
-- Foods with no energy value in the source data (0) are stored as 0 kcal.

alter table public.nutrition_foods
  add column if not exists fnri_id text;

-- A previous partial/manual import may already contain duplicate FNRI IDs.
-- Remove the index and all old rows before rebuilding the unique index.
drop index if exists public.idx_nutrition_foods_fnri_id;
delete from public.nutrition_foods;

create unique index idx_nutrition_foods_fnri_id
  on public.nutrition_foods (fnri_id)
  where fnri_id is not null;

-- Search by the English FNRI name, food group, or any Filipino alias.
-- SECURITY INVOKER keeps the existing nutrition_foods read RLS policy in force.
create or replace function public.search_nutrition_foods(search_query text)
returns setof public.nutrition_foods
language sql
stable
security invoker
set search_path = public
as $$
  select nf.*
  from public.nutrition_foods nf
  where length(trim(search_query)) >= 2
    and (
      nf.food_name ilike '%' || search_query || '%'
      or nf.category ilike '%' || search_query || '%'
      or exists (
        select 1
        from unnest(nf.aliases) as alias_name
        where alias_name ilike '%' || search_query || '%'
      )
    )
  order by
    case when lower(nf.food_name) = lower(search_query) then 0 else 1 end,
    nf.food_name
  limit 30;
$$;

grant execute on function public.search_nutrition_foods(text) to authenticated;

